CREATE TABLE IF NOT EXISTS game_cards(id TEXT PRIMARY KEY,data JSONB NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS card_classes(id TEXT PRIMARY KEY,data JSONB NOT NULL);
CREATE TABLE IF NOT EXISTS shop_packages(id TEXT PRIMARY KEY,data JSONB NOT NULL,version BIGINT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS wallets(user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,coins INTEGER NOT NULL DEFAULT 1000 CHECK(coins>=0));
CREATE TABLE IF NOT EXISTS card_inventory(user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,card_id TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),PRIMARY KEY(user_id,card_id));
CREATE TABLE IF NOT EXISTS pack_draws(user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,request_id TEXT NOT NULL,result JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(user_id,request_id));
CREATE TABLE IF NOT EXISTS admin_changes(id BIGSERIAL PRIMARY KEY,admin_id BIGINT REFERENCES admins(id),action TEXT NOT NULL,target TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
